/* logInqyDao1020 : 로그 목록 조회 */ SELECT SUB_DATA.* FROM ( SELECT L.LOG_ID , L.LOG_MSG , L.REQUEST_URI , L.IP_ADDRESS , L.REG_IDX , TO_CHAR(L.REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS REG_DT , L.REMARK , E.EMP_ID , E.EMP_NM , O.ORG_NM , COUNT(*) OVER() AS LIST_CNT , ROW_NUMBER() OVER(ORDER BY L.REG_DT DESC, L.LOG_ID DESC) AS NUM FROM LOG L LEFT OUTER JOIN EMP_INFO E ON E.EMP_IDX = L.REG_IDX LEFT OUTER JOIN ORG O ON O.ORG_CD = E.ORG_CD AND O.USE_YN = 'Y' WHERE 1=1
AND REGEXP_REPLACE(LOWER(E.EMP_NM), '[^0-9가-힣A-Za-z]', '') LIKE '%' || REGEXP_REPLACE(LOWER(#{srchNm, jdbcType=VARCHAR}), '[^0-9가-힣A-Za-z]', '') || '%'
AND L.REG_DT >= TO_DATE(#{srchSdt, jdbcType=VARCHAR}, 'YYYY-MM-DD')
AND L.REG_DT < TO_DATE(#{srchEdt, jdbcType=VARCHAR}, 'YYYY-MM-DD') + 1
) SUB_DATA WHERE 1=1
AND SUB_DATA.NUM BETWEEN #{sIdx, jdbcType=VARCHAR} AND #{eIdx, jdbcType=VARCHAR}
ORDER BY SUB_DATA.NUM ASC

