/* logProcDao1010 : 로그 등록 처리 */
INSERT INTO LOG (
		LOG_ID
	, 	LOG_MSG
	, 	LOG_CONT
	, 	REQUEST_URI
	, 	IP_ADDRESS
	, 	REG_IDX
	, 	REG_DT
	, 	REMARK
)
VALUES (
		(SELECT 'LOG_' || LPAD(NVL(MAX(TO_NUMBER(REPLACE(LOG_ID, 'LOG_', ''))), 0) + 1, 4, '0') FROM LOG)
	, 	#{logMsg, jdbcType=VARCHAR}
	, 	#{logCont, jdbcType=CLOB}
	, 	#{requestUri, jdbcType=VARCHAR}
	, 	#{ipAddress, jdbcType=VARCHAR}
	, 	#{regIdx, jdbcType=VARCHAR}
	, 	SYSDATE
	, 	#{remark, jdbcType=VARCHAR}
)
